CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$SELECT NULLIF(current_setting('test.uid',true),'')::uuid$$;
CREATE FUNCTION fn_caller_is_engine() RETURNS boolean LANGUAGE sql AS $$SELECT COALESCE(current_setting('test.engine',true),'true')='true'$$;
CREATE TABLE profiles(id uuid PRIMARY KEY,username text);
CREATE TABLE clubs(id uuid PRIMARY KEY,name text,owner_id uuid REFERENCES profiles(id));
CREATE TABLE unions(id uuid PRIMARY KEY,name text,owner_id uuid REFERENCES profiles(id));
CREATE TABLE union_admins(union_id uuid,user_id uuid);
CREATE TABLE club_members(club_id uuid,user_id uuid,role text,status text);
CREATE TABLE agents(id uuid PRIMARY KEY,user_id uuid,club_id uuid);
CREATE FUNCTION fn_is_union_overseer(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$SELECT EXISTS(SELECT 1 FROM unions WHERE id=$1 AND owner_id=$2)$$;
CREATE TABLE social_pages(id uuid PRIMARY KEY,linked_entity_id text,linked_entity_type text);
CREATE TABLE social_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),is_group boolean,group_name text,context_entity_id uuid,context_entity_type text,created_at timestamptz DEFAULT now(),last_message_at timestamptz,last_message_preview text,updated_at timestamptz);
CREATE TABLE social_conversation_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid REFERENCES social_conversations(id),user_id uuid REFERENCES profiles(id),context_entity_id uuid,context_entity_type text,UNIQUE(conversation_id,user_id));
CREATE TABLE social_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid REFERENCES social_conversations(id),sender_id uuid REFERENCES profiles(id),content text NOT NULL,message_type text,media_metadata jsonb);
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES profiles(id),type text,title text,message text,data jsonb,read boolean,action_url text,metadata jsonb);
CREATE TABLE credit_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agent_id uuid REFERENCES agents(id),period_start timestamptz,period_end timestamptz,debt_owed numeric,due_date timestamptz);
CREATE TABLE credit_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid REFERENCES credit_invoices(id),amount numeric,payment_method text,transaction_id text,created_at timestamptz DEFAULT now());
CREATE TABLE chip_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),from_type text,from_entity_id uuid,to_type text,to_entity_id uuid,amount numeric,category text,club_id uuid,union_id uuid,status text DEFAULT 'posted',metadata jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE settlement_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES clubs(id),period_id uuid NOT NULL,invoice_type text,from_entity_type text,from_entity_id text,to_entity_type text,to_entity_id text,gross_amount numeric,net_amount numeric,deductions numeric,breakdown jsonb,status text,chips_transferred boolean DEFAULT false,transferred_at timestamptz,message_sent boolean DEFAULT false,message_sent_at timestamptz,notes text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),due_at timestamptz,invoice_number text UNIQUE);
ALTER TABLE settlement_invoices ADD CONSTRAINT settlement_invoices_invoice_type_check CHECK(true), ADD CONSTRAINT settlement_invoices_from_entity_type_check CHECK(true);
ALTER TABLE settlement_invoices ENABLE ROW LEVEL SECURITY;
GRANT USAGE ON SCHEMA public,auth TO authenticated,service_role;
GRANT SELECT ON settlement_invoices TO authenticated;
CREATE TABLE ca_declared_money_triggers(table_name text,trigger_name text,note text);
CREATE TABLE fixture_effects(id uuid);
CREATE FUNCTION assert_true(boolean,text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF $1 IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',$2;END IF;RAISE NOTICE 'PASS: %',$2;END$$;
CREATE FUNCTION refuses(text,text) RETURNS boolean LANGUAGE plpgsql AS $$BEGIN EXECUTE $1;RETURN false;EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'caught: %',SQLERRM;RETURN SQLSTATE=$2;END$$;
CREATE FUNCTION fixture_transfer(p_id uuid,p_from uuid,p_to uuid,p_club uuid,p_category text DEFAULT 'commission',p_from_type text DEFAULT 'club_treasury',p_to_type text DEFAULT 'player_wallet') RETURNS void LANGUAGE plpgsql AS $$BEGIN
 INSERT INTO fixture_effects VALUES(p_id);
 INSERT INTO chip_ledger(id,from_type,from_entity_id,to_type,to_entity_id,amount,category,club_id) VALUES(p_id,p_from_type,p_from,p_to_type,p_to,12.34,p_category,p_club);
END$$;
